(()=>{
 const box=document.getElementById('verification-result');
 function node(tag,text,cls){const e=document.createElement(tag);e.textContent=text;if(cls)e.className=cls;return e}
 async function refresh(){try{const r=await fetch('/api/pipeline-verification');if(!r.ok){box.replaceChildren(node('p','Run the pipeline to validate and compare its output.','helper'));return}const d=await r.json();box.replaceChildren();box.append(node('h3','Original and output ZIP'));
 const hashes=node('p','Original SHA-256: '+d.original_sha256+'\nOutput SHA-256: '+d.output_sha256,'verification-hashes');box.append(hashes);
 box.append(node('p',`${d.changed_files.length} file(s) changed · ${d.intent.route_fields_verified} route fields and ${d.intent.stop_records_verified} stop records read back from the output.`,'helper'));
 const files=node('div','','verification-files');for(const f of d.changed_files){const row=node('p',`${f.file} · rows ${f.before_rows??'—'} → ${f.after_rows??'—'}`,'helper');files.append(row)}if(!d.changed_files.length)files.append(node('p','No file contents changed.','helper'));box.append(files);
 if(d.intent.route_fields.length){box.append(node('h3','Route field changes'));for(const change of d.intent.route_fields)box.append(node('p',`Route ${change.route_id} · ${change.field}: ${change.original||'(empty)'} → ${change.output||'(empty)'}`,'verification-hashes'))}
 const changed=d.check_deltas.filter(x=>x.delta!==0),increased=changed.filter(x=>x.delta>0);box.append(node('h3','Basic local checks'));box.append(node('p',increased.length?`${increased.length} check(s) have more findings in the output; inspect below.`:'No increases in the implemented local check counts.','helper'));
 for(const c of changed)box.append(node('p',`${c.rule}: ${c.original} → ${c.output} (${c.delta>0?'+':''}${c.delta})`,'verification-hashes'));
 if(!changed.length)box.append(node('p','No changes in local check counts.','helper'));
 const canonical=d.canonical,available=canonical.original.status==='completed'&&canonical.output.status==='completed';box.append(node('h3','Independent GTFS validation'));box.append(node('p',available?'The locally installed MobilityData GTFS Schedule Validator was run on the original and output ZIPs. The saved results are summarized below.':'Not run for both feeds. '+(canonical.output.reason||canonical.original.reason||'Check the validator configuration.'),'helper'));if(available){for(const severity of ['ERROR','WARNING','INFO']){const total=report=>(report.notices||[]).filter(x=>x.severity===severity).reduce((sum,x)=>sum+(x.totalNotices||0),0);box.append(node('p',`${severity}: ${total(canonical.original.report)} → ${total(canonical.output.report)}`,'verification-hashes'))}for(const c of d.canonical_deltas){const detail=document.createElement('details'),summary=node('summary',`${c.severity} · ${c.rule}: ${c.original} → ${c.output} (${c.delta>0?'+':''}${c.delta})`),notice=(canonical.output.report.notices||[]).find(x=>x.code===c.rule&&x.severity===c.severity);detail.append(summary);detail.append(node('p',c.delta>0?'This rule has more notices in the output. Examples are samples from the validator, not a change-by-change attribution.':'This rule has fewer notices in the output.','helper'));for(const sample of (notice?.sampleNotices||[]).slice(0,3))detail.append(node('p',Object.entries(sample).map(([k,v])=>k+': '+String(v)).join(' · '),'verification-hashes'));box.append(detail)}if(!d.canonical_deltas.length)box.append(node('p','No changes in canonical notice counts.','helper'));for(const [label,result] of [['Original feed',canonical.original],['Output feed',canonical.output]]){const details=document.createElement('details'),summary=node('summary',label+' validator notices'),notices=result.report.notices||[];details.append(summary);if(!notices.length)details.append(node('p','No notices.','helper'));for(const notice of notices)details.append(node('p',`${notice.severity||'NOTICE'} · ${notice.code||'Unknown rule'}: ${notice.totalNotices??0}`,'verification-hashes'));box.append(details)}}box.append(node('p',d.scope+' '+d.intent.note,'helper'));
 }catch(e){box.replaceChildren(node('p','Could not load the output verification: '+e.message,'helper'))}}
 refresh();window.addEventListener('pipeline-updated',refresh);
})();
